// Divide a telemetria em saídas separadas.
const p = msg.payload || {};
const id = p.device_id || 'desconhecido';

// Saída 1: temperatura
let temp = null;
if (p.temperatura_c !== undefined && p.temperatura_c !== null) {
    temp = { topic: id, payload: p.temperatura_c };
}

// Saída 2: vibração (RMS)
let vib = null;
if (p.vibracao) {
    vib = { topic: id, payload: p.vibracao.rms_g };
}

// Saída 3: objeto completo para o avaliador de alarmes
const full = { payload: p };

return [temp, vib, full];

// Limites de alarme — calibre conforme o equipamento.
const LIM = {
    temp:  { atencao: 60,  critico: 75 },
    vibRms:{ atencao: 0.5, critico: 1.0 }
};

const p = msg.payload || {};
const id = p.device_id || 'desconhecido';
let nivel = 'normal';
const motivos = [];

function avalia(valor, lim, nome, unid) {
    if (valor === undefined || valor === null) return;
    if (valor >= lim.critico) {
        nivel = 'critico';
        motivos.push(`${nome} crítico: ${valor}${unid}`);
    } else if (valor >= lim.atencao) {
        if (nivel !== 'critico') nivel = 'atencao';
        motivos.push(`${nome} em atenção: ${valor}${unid}`);
    }
}

avalia(p.temperatura_c, LIM.temp, 'Temperatura', '°C');
if (p.vibracao) avalia(p.vibracao.rms_g, LIM.vibRms, 'Vibração RMS', 'g');

const cores = { normal: '#00b500', atencao: '#e6e600', critico: '#ca3838' };
msg.payload = motivos.length ? `${id}: ${motivos.join(' | ')}` : `${id}: OK`;
msg.color = cores[nivel];
msg.nivel = nivel;
return msg;

// SUBSTITUA por leitura real do inversor PowerFlex 525 via EtherNet/IP:
//  use node-red-contrib-cip-ethernet-ip para ler o parametro de
//  Corrente de Saida (b003) do drive e conecte a saida do no aqui.
//  Confirme o mapeamento CIP/parametro no manual 520COM-UM001.
// Valor simulado enquanto a leitura EtherNet/IP nao esta ligada:
const base = 12.0;
const corrente = base + (Math.random() * 2 - 1); // 11..13 A
msg.payload = Math.round(corrente * 10) / 10;
msg.topic = 'powerflex-01';
return msg;
